namespace sv_739c800450164556b3e879c7647c1455;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

@rendermode InteractiveServer

<span class="badge rounded-pill" style="background-color: @GetBadgeColor();">
    @GetThemeLabel()
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string GetThemeLabel() => Theme?.Theme switch
    {
        Theme.Dark => "🌙 Dark",
        Theme.System => "💻 System",
        _ => "☀️ Light"
    };

    private string GetBadgeColor() => Theme?.AccentColor ?? "#0d6efd";
}

@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Color Mode</label>
            <select class="form-select" value="@CurrentThemeValue" @onchange="OnThemeChanged">
                <option value="Light">☀️ Light</option>
                <option value="Dark">🌙 Dark</option>
                <option value="System">💻 System</option>
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   value="@CurrentAccentColor" @onchange="OnAccentChanged" />
        </div>

        <p class="text-muted small mt-3">
            Current: <strong>@CurrentThemeValue</strong> mode,
            accent <span class="badge" style="background-color: @CurrentAccentColor;">@CurrentAccentColor</span>
        </p>
    </div>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private string CurrentThemeValue => Theme?.Theme.ToString() ?? "Light";
    private string CurrentAccentColor => Theme?.AccentColor ?? "#0d6efd";

    private async Task OnThemeChanged(ChangeEventArgs e)
    {
        var newTheme = Enum.Parse<Theme>(e.Value?.ToString() ?? "Light");
        var updated = new ThemeInfo
        {
            Theme = newTheme,
            AccentColor = CurrentAccentColor
        };
        await ThemeSource.NotifyChangedAsync(updated);
    }

    private async Task OnAccentChanged(ChangeEventArgs e)
    {
        var updated = new ThemeInfo
        {
            Theme = Theme?.Theme ?? Theme.Light,
            AccentColor = e.Value?.ToString() ?? "#0d6efd"
        };
        await ThemeSource.NotifyChangedAsync(updated);
    }
}

